21	// What the intent and plan leave out rather than send empty: an unset field,
22	// an empty list, a false truncated flag.
23	void drop_empty(json& value)
24	{
25	    if (!value.is_object() && !value.is_array())
26	        return;
27	    for (json& child : value)
28	        drop_empty(child);
29	    if (!value.is_object())
30	        return;
31	    for (auto it = value.begin(); it != value.end();) {
32	        const bool empty = it->is_null() || (it->is_string() && it->get_ref<const std::string&>().empty()) ||
33	                           ((it->is_array() || it->is_object()) && it->empty()) ||
34	                           (it.key() == "truncated" && *it == false);
35	        it = empty ? value.erase(it) : std::next(it);
36	    }
37	}
38	
39	json workspace_json(const AgentRequest& request)
40	{
41	    const Workspace::WorkspaceSnapshot& workspace = request.workspace;
42	    json plates = json::array();
43	    for (const auto& plate : workspace.plates) {
44	        json objects = json::array();
45	        for (const auto& object : plate.objects)
46	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
47	                                   {"instances", object.instances.size()}});
48	        plates.push_back(json{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
49	                              {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}});
50	    }
51	    json selected = json::array();
52	    for (const auto id : workspace.selected_objects)
53	        selected.push_back(std::to_string(id.value()));
54	    json result{{"sessionId", std::to_string(workspace.session.value())},
55	                {"revision", workspace.revision},
56	                {"projectName", workspace.setup.project_name},
57	                {"printerPreset", workspace.setup.printer_preset},
58	                {"filamentPreset", workspace.setup.filament_preset},
59	                {"selectedObjectIds", std::move(selected)},
60	                {"plates", std::move(plates)}};
61	    if (!workspace.setup.process_preset.empty())
62	        result["processPreset"] = workspace.setup.process_preset;
63	    // The model's own notes, in the shapes workspace_inspect's intent and plan
64	    // sections return, less their timestamps: on the next turn it reads what
65	    // it recorded without spending a call on it.
66	    json intent = intent_section_result(request.intent);
67	    intent["setupTitle"] = request.setup_title;
68	    for (json& field : intent["fields"])
69	        field.erase("updatedAt");
70	    drop_empty(intent);
71	    if (!intent.empty())
72	        result["intent"] = std::move(intent);
73	    const json full_plan = plan_section_result(request.plan);
74	    json plan{{"headline", full_plan["headline"]}, {"decisions", full_plan["decisions"]},
75	              {"assumptions", full_plan["assumptions"]}, {"truncated", full_plan["truncated"]}};
76	    drop_empty(plan);
77	    if (!plan.empty())
78	        result["plan"] = std::move(plan);
79	    return result;
80	}
