import json,re,collections
a=json.load(open('/tmp/claude/requests_before.json'))['cases']; b=json.load(open('tests/project_prompt/requests.json'))['cases']
IGN=re.compile(r'(updatedAt|revision|Revision|sessionId|objectId|plateId|partId|handle$|facesDown|objectIds|likelyDuplicates|selection/items|activePlateId|plateIds|/id$|parallel_tool_calls|project/path|content)')
def norm(s):
    if isinstance(s,str) and s[:1] in '{[':
        try: return json.loads(s)
        except: pass
    return s
out=collections.defaultdict(list)
def walk(x,y,path,case):
    x,y=norm(x),norm(y)
    if isinstance(x,dict) and isinstance(y,dict):
        for k in set(x)|set(y):
            if k not in x or k not in y: out[case].append((path+'/'+k,'missing in '+('old' if k not in x else 'new'))); continue
            walk(x[k],y[k],path+'/'+k,case)
    elif isinstance(x,list) and isinstance(y,list):
        if len(x)!=len(y): out[case].append((path,'len %d->%d'%(len(x),len(y)))); return
        for i,(p,q) in enumerate(zip(x,y)): walk(p,q,path+'/%d'%i,case)
    elif x!=y and not IGN.search(path):
        out[case].append((path,(str(x)[:100],str(y)[:100])))
for c in a: walk(a[c],b[c],'',c)
for c,v in out.items():
    print('==',c,len(v))
    for p,d in v[:12]: print('  ',p,d)
